struct SAM {
    static const int ALPH = 26;
    struct State {
        int len = 0, link = -1;
        int next[ALPH];
        long long cnt = 0;     
        State() { memset(next, -1, sizeof next); }
    };

    vector<State> st;
    vector<int> vist;
    int last;
    int timestamp = 1;

    SAM(int maxlen = 500000) {
        st.reserve(2 * maxlen);
        vist.reserve(2 * maxlen);
        st.push_back(State());
        vist.push_back(0);
        last = 0;
    }

    int extend(char c) {
        int C = c - 'a';
        int cur = st.size();
        st.push_back(State());
        vist.push_back(0);
        st[cur].len = st[last].len + 1;
        int p = last;
        while (p != -1 && st[p].next[C] == -1) {
            st[p].next[C] = cur;
            p = st[p].link;
        }
        if (p == -1) {
            st[cur].link = 0;
        } else {
            int q = st[p].next[C];
            if (st[p].len + 1 == st[q].len) {
                st[cur].link = q;
            } else {
                int clone = st.size();
                st.push_back(st[q]);
                vist.push_back(0);
                st[clone].len = st[p].len + 1;
                while (p != -1 && st[p].next[C] == q) {
                    st[p].next[C] = clone;
                    p = st[p].link;
                }
                st[q].link = st[cur].link = clone;
            }
        }
        last = cur;
        return cur;
    }

    void add_string(const string &s) {
        last = 0;
        vector<int> ends;
        ends.reserve(s.size());
        for (char c : s) ends.push_back(extend(c));
        sort(ends.begin(), ends.end());
        ends.erase(unique(ends.begin(), ends.end()), ends.end());

        ++timestamp;
        for (int v : ends) {
            int u = v;
            while (u != -1 && vist[u] != timestamp) {
                vist[u] = timestamp;
                st[u].cnt++;
                u = st[u].link;
            }
        }
    }

    void erase_string(const string &s) {
        int v = 0;
        vector<int> ends;
        for (char c : s) {
            v = st[v].next[c - 'a'];
            if (v < 0) return;  
            ends.push_back(v);
        }
        sort(ends.begin(), ends.end());
        ends.erase(unique(ends.begin(), ends.end()), ends.end());

        ++timestamp;
        for (int v2 : ends) {
            int u = v2;
            while (u != -1 && vist[u] != timestamp) {
                vist[u] = timestamp;
                st[u].cnt--;
                u = st[u].link;
            }
        }
    }

    long long query(const string &s) const {
        int v = 0;
        for (char c : s) {
            v = st[v].next[c - 'a'];
            if (v < 0) return 0;
        }
        return st[v].cnt;
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);

    int n;
    cin >> n;
    SAM sam(500005);
    string s;
    for (int i = 0; i < n; i++) {
        cin >> s;
        sam.add_string(s);
    }

    int q;
    cin >> q;
    while (q--) {
        char op;
        cin >> op >> s;
        if (op == 'i') {
            sam.add_string(s);
        } else if (op == 'e') {
            sam.erase_string(s);
        } else {
            cout << sam.query(s) << '\n';
        }
    }
}